      error: (err: unknown) => {
        this.generating.set(false);
        this.generateError.set(
          err instanceof HttpErrorResponse && err.status === 400
            ? 'The to-date cannot be before the from-date.'
            : 'Could not generate the periods.',
        );
      },
    });
